import React, { useState, useEffect } from 'react';
import { Button, Form, Container } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';

const AuthForm = ({ setUser }) => {
  const [email, setEmail] = useState(''); // Initialize with empty string
  const [password, setPassword] = useState(''); // Initialize with empty string
  const [role, setRole] = useState('user'); // Add role state
  const [isLogin, setIsLogin] = useState(true); // State to toggle between login and signup
  const navigate = useNavigate();

  useEffect(() => {
    // Clear email and password fields when the component mounts
    setEmail('');
    setPassword('');
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const users = JSON.parse(localStorage.getItem('users')) || [];
    if (isLogin) {
      // Handle login
      const user = users.find((user) => user.email === email && user.password === password);
      if (user) {
        localStorage.setItem('authToken', 'sample-token'); // Mock token storage
        localStorage.setItem('role', user.role); // Store role in localStorage
        setUser({ email: user.email, role: user.role }); // Update user state with role
        navigate(user.role === 'admin' ? '/admin-dashboard' : '/');
      } else {
        alert('User not found. Please sign up.');
        setIsLogin(false); // Switch to signup form
      }
    } else {
      // Handle signup
      if (users.find((user) => user.email === email)) {
        alert('User already exists. Please log in.');
        setIsLogin(true); // Switch to login form
      } else {
        const newUser = { email, password, role };
        users.push(newUser);
        localStorage.setItem('users', JSON.stringify(users));
        alert('Signup successful. Please log in.');
        setIsLogin(true); // Switch to login form
      }
    }
  };

  const toggleMode = () => {
    setIsLogin(!isLogin);
    setEmail(''); // Clear email field when switching modes
    setPassword(''); // Clear password field when switching modes
  };

  return (
    <Container className="mt-4">
      <h2 className="text-center">{isLogin ? 'Login' : 'Signup'}</h2>
      <Form onSubmit={handleSubmit} autoComplete="off">
        <Form.Group controlId="formBasicEmail">
          <Form.Label>Email address</Form.Label>
          <Form.Control
            type="email"
            placeholder="Enter email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            name="email"
            autoComplete="new-email" // Prevent autofill
          />
        </Form.Group>

        <Form.Group controlId="formBasicPassword">
          <Form.Label>Password</Form.Label>
          <Form.Control
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            name="password"
            autoComplete="new-password" // Prevent autofill
          />
        </Form.Group>

        {!isLogin && (
          <Form.Group controlId="formBasicRole">
            <Form.Label>Role</Form.Label>
            <Form.Control
              as="select"
              value={role}
              onChange={(e) => setRole(e.target.value)}
              required
            >
              <option value="user">User</option>
              <option value="admin">Admin</option>
            </Form.Control>
          </Form.Group>
        )}

        <Button variant="primary" type="submit" className="mt-3">
          {isLogin ? 'Login' : 'Signup'}
        </Button>
      </Form>
      <Button variant="link" onClick={toggleMode} className="mt-3">
        {isLogin ? 'Switch to Signup' : 'Switch to Login'}
      </Button>
    </Container>
  );
};

export default AuthForm;
